    out.push(sel('year', 'Năm Phát Hành', [['Tất Cả', ''], ['2026', '2026'], ['2025', '2025'], ['2024', '2024'], ['2023', '2023'], ['2022', '2022'], ['2021', '2021'], ['2020', '2020'], ['Trước 2020', 'before_2020']]));
